#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int n;
    cin >> n;
    int pos[1000];
    for (int i = 0; i < n; i++) {
        cin >> pos[i];
    }
    int distance = 0;
    for (int i = 1; i < n; i++) {
        int step = pos[i] - pos[i - 1];
        if (step < 0) {
            step = -step;
        }
        distance += step;
    }
    int back = pos[n - 1] - pos[0];
    if (back < 0) {
        back = -back;
    }
    distance += back;
    int farthest = pos[0];
    for (int i = 1; i < n; i++) {
        if (pos[i] > farthest) {
            farthest = pos[i];
        }
    }
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += pos[i];
    }
    double average = sum / (double)n;
    int above = 0;
    for (int i = 0; i < n; i++) {
        if (pos[i] > average) {
            above++;
        }
    }
    cout << "Total distance: " << distance << endl;
    cout << "Farthest position: " << farthest << endl;
    cout << fixed << setprecision(2) << "Average position: " << average << endl;
    cout << "Above average: " << above << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int price[1000];
    for (int i = 0; i < n; i++) {
        cin >> price[i];
    }
    int bestProfit = 0;
    int buyDay = -1;
    int sellDay = -1;
    int minPrice = price[0];
    int minDay = 0;
    for (int j = 1; j < n; j++) {
        int profit = price[j] - minPrice;
        if (profit > bestProfit) {
            bestProfit = profit;
            buyDay = minDay;
            sellDay = j;
        }
        if (price[j] < minPrice) {
            minPrice = price[j];
            minDay = j;
        }
    }
    if (buyDay == -1) {
        cout << "No profitable trade" << endl;
    } else {
        cout << "Buy day: " << buyDay << endl;
        cout << "Sell day: " << sellDay << endl;
        cout << "Profit: " << bestProfit << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int temp[1000];
    for (int i = 0; i < n; i++) {
        cin >> temp[i];
    }
    int threshold;
    cin >> threshold;
    int bestLen = 0;
    int bestStart = 0;
    int curLen = 0;
    int curStart = 0;
    for (int i = 0; i < n; i++) {
        if (temp[i] > threshold) {
            if (curLen == 0) {
                curStart = i;
            }
            curLen++;
            if (curLen > bestLen) {
                bestLen = curLen;
                bestStart = curStart;
            }
        } else {
            curLen = 0;
        }
    }
    cout << "Longest streak: " << bestLen << " day(s)" << endl;
    cout << "Start day: " << bestStart + 1 << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int arr[1000];
    int arranged[1000];
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }
    int k = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] % 2 == 0) {
            arranged[k++] = arr[i];
        }
    }
    for (int i = 0; i < n; i++) {
        if (arr[i] % 2 != 0) {
            arranged[k++] = arr[i];
        }
    }
    int evens = 0;
    int odds = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] % 2 == 0) {
            evens++;
        } else {
            odds++;
        }
    }
    for (int i = 0; i < n; i++) {
        cout << arranged[i];
        if (i < n - 1) {
            cout << " ";
        }
    }
    cout << endl;
    cout << "Even codes: " << evens << endl;
    cout << "Odd codes: " << odds << endl;
    return 0;
}

